import re, sys

REG = {'a', 'b', 'c', 'd'}
LIT = re.compile(r'-?\d+')
ARITY = {'set': 2, 'add': 2, 'mul': 2, 'mod': 2, 'dec': 1, 'jnz': 2, 'skp': 2, 'out': 1}


def parse(text):
    prog = []
    for n, raw in enumerate(text.splitlines(), 1):
        line = raw.split(';', 1)[0].strip()
        if not line:
            continue
        parts = line.split()
        op, args = parts[0], parts[1:]
        if op not in ARITY or len(args) != ARITY[op]:
            raise ValueError(f'line {n}: bad instruction {raw!r}')
        if op in ('set', 'add', 'mul', 'mod', 'dec') and args[0] not in REG:
            raise ValueError(f'line {n}: bad destination {raw!r}')
        for x in args:
            if x not in REG and not LIT.fullmatch(x):
                raise ValueError(f'line {n}: bad operand {x!r}')
        prog.append((op, args))
    return prog


def run(prog, cap=50_000_000):
    r = {k: 0 for k in REG}
    val = lambda x: r[x] if x in REG else int(x)
    pc, steps, out = 0, 0, []
    while 0 <= pc < len(prog):
        steps += 1
        if steps > cap:
            raise RuntimeError('step cap hit')
        op, (*a,) = prog[pc]
        nxt = pc + 1
        if op == 'set':
            r[a[0]] = val(a[1]) % 65536
        elif op == 'add':
            r[a[0]] = (r[a[0]] + val(a[1])) % 65536
        elif op == 'mul':
            r[a[0]] = (r[a[0]] * val(a[1])) % 65536
        elif op == 'mod':
            y = val(a[1])
            if y > 0:
                r[a[0]] = r[a[0]] % y
        elif op == 'dec':
            r[a[0]] = max(r[a[0]] - 1, 0)
        elif op == 'jnz':
            if val(a[0]) != 0:
                nxt = pc + val(a[1])
        elif op == 'skp':
            if val(a[0]) < val(a[1]):
                nxt = pc + 2
        elif op == 'out':
            out.append(val(a[0]))
        pc = nxt
    return out, steps


if __name__ == '__main__':
    text = open(sys.argv[1], encoding='utf-8').read()
    out, steps = run(parse(text))
    print('outputs:', out)
    print('count:', len(out), 'sum:', sum(out), 'steps:', steps)
    print(f'{sum(out)} {steps}')
